f32 absFloat();                                /* extern */

/* Returns -1, 0 or 1 for an analog axis value: 0 inside the 0.75 threshold, otherwise the sign of axis. */ f32 stickDirectionWithDeadzone(f32 axis) {
    f32 direction;

    direction = 0.0f;
    if (absFloat() >= 0.75f) {
        direction = -1.0f;
        if (axis > 0.0f) {
            direction = 1.0f;
        }
    }
    return direction;
}
